/** 
 * Returns true if a Payload should be transmit to a peer given the peer's supported capabilities.
 */
private static boolean shouldTransmitPayloadToPeer(Capabilities peerCapabilities,NetworkPayload payload){
  if (!(payload instanceof ProtectedStoragePayload || payload instanceof PersistableNetworkPayload))   return false;
  if (!(payload instanceof CapabilityRequiringPayload))   return true;
  boolean shouldTransmit=peerCapabilities.containsAll(((CapabilityRequiringPayload)payload).getRequiredCapabilities());
  if (!shouldTransmit) {
    log.debug("We do not send the message to the peer because they do not support the required capability for that message type.\n" + "storagePayload is: " + Utilities.toTruncatedString(payload));
  }
  return shouldTransmit;
}
